/// <summary>
/// Each handheld's item sync as it last reported it (HSMobileOpsSkuPageSvc/reportSync): sent by
/// the app at the end of every item sync, finished or failed. Sync health reads it to show
/// which devices are up to date, which are failing and which have gone quiet.
///
/// One row per device and company. A device that cannot reach D365FO cannot report; it shows up
/// as stale once its last successful sync is older than staleHours().
/// </summary>
public class HSMobileOpsDeviceSync extends common
{
}

Method.Source:
/// <summary>
/// A device whose last successful item sync is older than this is stale. The item sync runs
/// once a day, on Wi-Fi while charging, so two days allows for a missed night.
/// </summary>
public static int staleHours()
{
    return 48;
}

/// <summary>Records one device's report; the caller has checked the company and the device id.</summary>
public static void report(HSMobileOpsSkuSyncReport _report)
{
    HSMobileOpsDeviceSync row;
    utcdatetime           now = DateTimeUtil::utcNow();

    ttsbegin;
    select forUpdate firstOnly row
        where row.DeviceId == _report.parmDeviceId();
    row.DeviceId      = _report.parmDeviceId();
    row.Warehouse     = _report.parmWarehouse();
    row.Scope         = _report.parmScope();
    row.AppVersion    = subStr(_report.parmAppVersion(), 1, 32);
    row.LastReportUtc = now;
    row.LastSeenUtc   = now;
    if (_report.parmSucceeded())
    {
        row.LastSuccessUtc = now;
        row.LastFull       = _report.parmFull() ? NoYes::Yes : NoYes::No;
        row.Items          = _report.parmItems();
        row.Barcodes       = _report.parmBarcodes();
        row.SyncSeconds    = _report.parmSeconds();
    }
    else
    {
        row.LastErrorUtc = now;
        row.LastError    = subStr(_report.parmMessage(), 1, 250);
    }
    row.HealthStatus = row.computeHealth();
    if (row.RecId)
    {
        row.update();
    }
    else
    {
        row.insert();
    }
    ttscommit;
}

/// <summary>Its last sync failed (an error after the last success).</summary>
public boolean isFailing()
{
    return this.LastErrorUtc && this.LastErrorUtc > this.LastSuccessUtc;
}

/// <summary>No successful item sync for staleHours().</summary>
public boolean isStale()
{
    return !this.LastSuccessUtc
        || DateTimeUtil::getDifference(DateTimeUtil::utcNow(), this.LastSuccessUtc) > HSMobileOpsDeviceSync::staleHours() * 3600;
}

/// <summary>What needs a look, in words - see computeHealth.</summary>
public display str health()
{
    int64 hours;

    switch (this.computeHealth())
    {
        case HSMobileOpsDeviceHealth::Retired:
            return 'Retired device';
        case HSMobileOpsDeviceHealth::Failing:
            return 'Failing: ' + this.LastError;
        case HSMobileOpsDeviceHealth::QueueStuck:
            return this.QueueFailed
                ? strFmt('%1 postings refused - see Posting queue', this.QueueFailed)
                : strFmt('%1 postings waiting since %2', this.QueuePending, this.OldestQueuedUtc);
        case HSMobileOpsDeviceHealth::NeverSynced:
            return 'No successful item sync yet';
        case HSMobileOpsDeviceHealth::Stale:
            hours = DateTimeUtil::getDifference(DateTimeUtil::utcNow(), this.LastSuccessUtc) div 3600;
            return hours >= 48 ? strFmt('Stale: last sync %1 days ago', hours div 24) : strFmt('Stale: last sync %1 hours ago', hours);
        case HSMobileOpsDeviceHealth::Offline:
            hours = DateTimeUtil::getDifference(DateTimeUtil::utcNow(), this.lastSeen()) div 3600;
            return strFmt('Not seen for %1 hours', hours);
    }
    return 'OK';
}

/// <summary>
/// The device's health now (16 Nov 2026), the worst first: retired (Hub devices, not active),
/// failing (last sync failed), postings stuck (any refused, or one waiting over stuckMinutes),
/// no sync yet, stale (no successful sync for staleHours), not seen (nothing for offlineHours).
/// </summary>
public HSMobileOpsDeviceHealth computeHealth()
{
    HSMobileOpsDevice device;
    utcdatetime       now = DateTimeUtil::utcNow();
    utcdatetime       seen = this.lastSeen();

    select firstOnly RecId, IsActive from device
        where device.DeviceId == this.DeviceId;
    if (device.RecId && device.IsActive == NoYes::No)
    {
        return HSMobileOpsDeviceHealth::Retired;
    }
    if (this.isFailing())
    {
        return HSMobileOpsDeviceHealth::Failing;
    }
    if (this.QueueFailed > 0
        || (this.QueuePending > 0 && this.OldestQueuedUtc
            && DateTimeUtil::getDifference(now, this.OldestQueuedUtc) > HSMobileOpsDeviceSync::stuckMinutes() * 60))
    {
        return HSMobileOpsDeviceHealth::QueueStuck;
    }
    if (!this.LastSuccessUtc)
    {
        return HSMobileOpsDeviceHealth::NeverSynced;
    }
    if (this.isStale())
    {
        return HSMobileOpsDeviceHealth::Stale;
    }
    if (!seen || DateTimeUtil::getDifference(now, seen) > HSMobileOpsDeviceSync::offlineHours() * 3600)
    {
        return HSMobileOpsDeviceHealth::Offline;
    }
    return HSMobileOpsDeviceHealth::Ok;
}

/// <summary>The later of the last check-in and the last sync report.</summary>
public utcdatetime lastSeen()
{
    return this.LastSeenUtc > this.LastReportUtc ? this.LastSeenUtc : this.LastReportUtc;
}

/// <summary>
/// A device's check-in (16 Nov 2026): seen now, with what waits in its posting queue. The caller
/// has checked the company and the device id.
/// </summary>
public static void heartbeat(HSMobileOpsDeviceHeartbeat _beat)
{
    HSMobileOpsDeviceSync row;
    utcdatetime           now = DateTimeUtil::utcNow();

    ttsbegin;
    select forUpdate firstOnly row
        where row.DeviceId == _beat.parmDeviceId();
    row.DeviceId     = _beat.parmDeviceId();
    if (_beat.parmWarehouse())
    {
        row.Warehouse = _beat.parmWarehouse();
    }
    if (_beat.parmAppVersion())
    {
        row.AppVersion = subStr(_beat.parmAppVersion(), 1, 32);
    }
    row.LastSeenUtc     = now;
    row.QueuePending    = max(0, _beat.parmQueuePending());
    row.QueueFailed     = max(0, _beat.parmQueueFailed());
    row.OldestQueuedUtc = row.QueuePending > 0 && _beat.parmOldestQueuedSeconds() > 0
        ? DateTimeUtil::addSeconds(now, -_beat.parmOldestQueuedSeconds())
        : DateTimeUtil::minValue();
    row.HealthStatus    = row.computeHealth();
    if (row.RecId)
    {
        row.update();
    }
    else
    {
        row.insert();
    }
    ttscommit;
}

public display Name deviceName()
{
    HSMobileOpsDevice device;

    select firstOnly FriendlyName from device where device.DeviceId == this.DeviceId;
    return device.FriendlyName;
}

public display HSMobileOpsUserName lastUser()
{
    HSMobileOpsDevice device;

    select firstOnly LastUserName from device where device.DeviceId == this.DeviceId;
    return device.LastUserName;
}

/// <summary>Which items the device holds: every item, or the store's assortment.</summary>
public display str itemsOf()
{
    return this.Scope ? 'Store assortment' : 'All items';
}
